 related=["vyvanse","ritalin","adderall","topics:vyvanse-safety-faq"],
 faqs=[("Is Vyvanse better than Ritalin for focus?", "'Better' is individual. Trials show comparable symptom control; Vyvanse's smoother curve avoids mid-day peaks and crashes, while some people feel more 'normal' on methylphenidate."),
       ("Can you switch between them?", "Yes — doctors do it routinely, usually with a washout or direct switch at equivalent doses. Never adjust prescribed doses yourself.")],
